""") + POST_TAIL

CREATE_POST_B = POST_HEAD + indent("""pid = ''
try:
    pid = str(V.get('create_promise_args.product_id') or (V.get('create_promise_args') or {}).get('product_id') or '')
except Exception:
    pid = ''
if d.get('ok') is True:
