            d = {'ok': False, 'error': 'service_unavailable'}
            result['data'] = d
        if result.get('status') not in (None, 'success') or (result.get('status_code') or 200) >= 400:
            d['ok'] = False
"""
POST_TAIL = """except Exception:
    pass
"""


